// Bygger en rad till Error Log-sheetet.
// VIKTIGT: logga aldrig hemligheter eller känslig data.
// Endast nodnamn + felmeddelande — ingen stack, ingen input-data,
// inget dokumentinnehåll och inga lead-uppgifter.

const d = $input.first()?.json || {};
const ex = d.execution || {};
const wf = d.workflow || {};
const err = ex.error || {};

const pad = (n) => String(n).padStart(2, '0');
const now = new Date();
const tidpunkt = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}`;

const agent = wf.name || 'Okänt workflow';

// Vilket steg som failade
const nod = err.node?.name || ex.lastNodeExecuted || 'okänd nod';

// Felmeddelandet, normaliserat och kapat så inte stora datadumpar hamnar i loggen
let meddelande = (err.message || 'Okänt fel').toString().replace(/\s+/g, ' ').trim();
if (meddelande.length > 300) meddelande = meddelande.slice(0, 300) + '…';

return [{
  json: {
    'Tidpunkt': tidpunkt,
    'Agent': agent,
    'Vad som gick fel': `${nod}: ${meddelande}`
  }
}];
